# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KARBONHİDRAT, PROTEİN VE YAĞLARIN KİMYASAL SİNDİRİM TABLOSU</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Karbonhidratlar</text>\n  <text x="40" y="100" font-size="11.5" fill="#334155">• Başlangıç: AĞIZ (Tükürük sıvısı</text>\n  <text x="40" y="116" font-size="11.5" fill="#334155">  içindeki enzimlerle başlar).</text>\n  <text x="40" y="140" font-size="11.5" fill="#334155">• Midede: Kimyasal sindirimi</text>\n  <text x="40" y="156" font-size="11.5" fill="#334155">  gerçekleşmez.</text>\n  <text x="40" y="180" font-size="11.5" fill="#334155">• Bitiş: İNCE BAĞIRSAK (Pankreas</text>\n  <text x="40" y="196" font-size="11.5" fill="#334155">  öz suyu enzimleriyle tamamlanır).</text>\n  <text x="130" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Yapı Taşı: Glikoz (Basit Şeker)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Proteinler</text>\n  <text x="260" y="100" font-size="11.5" fill="#334155">• Ağızda: Kimyasal sindirimi</text>\n  <text x="260" y="116" font-size="11.5" fill="#334155">  gerçekleşmez (dişlerle mekanik).</text>\n  <text x="260" y="140" font-size="11.5" fill="#334155">• Başlangıç: MİDE (Mide öz suyu</text>\n  <text x="260" y="156" font-size="11.5" fill="#334155">  ve mide asidiyle başlar).</text>\n  <text x="260" y="180" font-size="11.5" fill="#334155">• Bitiş: İNCE BAĞIRSAK (Pankreas</text>\n  <text x="260" y="196" font-size="11.5" fill="#334155">  öz suyu enzimleriyle tamamlanır).</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Yapı Taşı: Amino Asit</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Yağlar</text>\n  <text x="480" y="100" font-size="11.5" fill="#334155">• Ağız ve Midede: Kimyasal</text>\n  <text x="480" y="116" font-size="11.5" fill="#334155">  sindirimi gerçekleşmez.</text>\n  <text x="480" y="140" font-size="11.5" fill="#334155">• Fiziksel Sindirim: İnce bağırsakta</text>\n  <text x="480" y="156" font-size="11.5" fill="#334155">  SAFRA sıvısı ile damlacıklara ayrılır.</text>\n  <text x="480" y="180" font-size="11.5" fill="#334155">• Başlangıç ve Bitiş: İNCE BAĞIRSAK</text>\n  <text x="480" y="196" font-size="11.5" fill="#334155">  (Pankreas öz suyu enzimleriyle).</text>\n  <text x="570" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Yapı Taşı: Yağ Asidi + Gliserol</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İNCE BAĞIRSAK (VİLLUSLAR) VE KALIN BAĞIRSAKTA EMİLİM OLAYI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İnce Bağırsakta Emilim (Villuslar)</text>\n  <path d="M 60 120 Q 75 80 90 120 Q 105 80 120 120 Q 135 80 150 120" fill="none" stroke="#16a34a" stroke-width="3"/>\n  <text x="230" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Villus (Tümör) Çıkıntıları</text>\n  <text x="230" y="118" text-anchor="middle" font-size="10.5" fill="#334155">Emilim yüzey alanını artırır</text>\n  <text x="44" y="150" font-size="11.5" fill="#334155">• Sindirimi tamamlanan besin içerikleri:</text>\n  <text x="54" y="168" font-size="11" fill="#15803d">Karbonhidrat, Protein ve Yağ yapı taşları</text>\n  <text x="44" y="190" font-size="11.5" fill="#334155">• Villuslardan kana geçenler:</text>\n  <text x="54" y="208" font-size="11" font-weight="bold" fill="#1e40af">Glikoz, Amino asit, Yağ asidi-Gliserol + Su, Vitamin, Mineral</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kalın Bağırsakta Emilim ve Özellikler</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Fiziksel veya kimyasal sindirim OLMAZ.</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• İç yüzeyinde villus çıkıntıları BULUNMAZ.</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• Besin atıklarında kalan SU, VİTAMİN ve</text>\n  <text x="378" y="164" font-size="11.5" fill="#334155">  MİNERALLERİN son emilimi burada yapılır.</text>\n  <text x="378" y="188" font-size="11.5" fill="#334155">• B ve K vitamini üreten yararlı bakteriler yaşar.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Atıklar anüs yoluyla vücuttan uzaklaştırılır</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİNDİRİM SİSTEMİNİN SAĞLIĞINI KORUMA YOLLARI (FB.7.3.2)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Sindirim Sistemi Rahatsızlıkları</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Ülser: Mide iç yüzeyinin mide asidiyle</text>\n  <text x="54" y="116" font-size="11" fill="#475569">tahriş olarak yara oluşturması.</text>\n  <text x="44" y="140" font-size="11.5" fill="#334155">• Gastrit: Mide iç yüzeyindeki mukozanın</text>\n  <text x="54" y="156" font-size="11" fill="#475569">iltihaplanması ve yanma hissi.</text>\n  <text x="44" y="180" font-size="11.5" fill="#334155">• Reflü: Asitli mide içeriğinin yemek</text>\n  <text x="54" y="196" font-size="11" fill="#475569">borusuna geri kaçması.</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Diğer: İshal, Kabızlık, Kolera, Diş Çürüğü</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sağlıklı Sindirim İçin Yapılması Gerekenler</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Yeterli, dengeli ve lifli (posalı) beslenmek</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• Lokmaları iyice çiğnemek, aşırı sıcak/soğuktan</text>\n  <text x="388" y="140" font-size="11" fill="#334155">ve asitli/baharatlı gıdalardan kaçınmak</text>\n  <text x="378" y="164" font-size="11.5" fill="#334155">• Dişleri düzenli fırçalamak, sert kabuk kırmamak</text>\n  <text x="378" y="188" font-size="11.5" fill="#334155">• Gün içinde yeterli su içmek ve stres, sigara,</text>\n  <text x="388" y="204" font-size="11" fill="#334155">alkol gibi zararlı alışkanlıklardan uzak durmak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
